function isAdminContext(ctx: { user: { role?: string; testRole?: string } | null }): boolean { return ctx.user?.role === "admin" || ctx.user?.testRole === "admin"; }
function getRequestCookie(req: { cookies?: Record<string, string>; headers: { cookie?: string } }, name: string) { return req.cookies?.[name] ?? parseCookie(req.headers.cookie ?? "")[name]; }
function assertRestaurantManager(ctx: { user: { role?: string; testRole?: string; restaurantId?: number } | null }) { if (!ctx.user || (!isAdminContext(ctx) && ctx.user.testRole !== "restaurant_admin")) throw new TRPCError({ code: "FORBIDDEN", message: "هذه العملية متاحة لمدير المطعم فقط" }); }
function assertTeamPermission(ctx: { user: { role?: string; testRole?: string } | null }, permission: TeamPermission) { if (isAdminContext(ctx) || ctx.user?.testRole === "restaurant_admin") return; if (!roleHasDefaultPermission(ctx.user?.testRole, permission)) throw new TRPCError({ code: "FORBIDDEN", message: `لا تملك صلاحية ${permission}` }); }
export function getCustomerCancellationDecision(input: { enabled: boolean; windowMinutes: number; status: string; acceptedAt?: Date | null; createdAt: Date; now?: Date }) { const referenceTime = input.acceptedAt ?? input.createdAt; const remainingMinutes = Math.max(0, input.windowMinutes - ((input.now ?? new Date()).getTime() - referenceTime.getTime()) / 60000); const allowed = input.enabled && ["new", "preparing"].includes(input.status) && remainingMinutes > 0; return { allowed, remainingMinutes: Math.ceil(remainingMinutes), reason: !input.enabled ? "disabled" : !["new", "preparing"].includes(input.status) ? "status" : remainingMinutes <= 0 ? "expired" : null }; }
function hashKioskPin(pin: string) { const salt = randomBytes(16).toString("base64"); return `scrypt$${salt}$${scryptSync(pin, Buffer.from(salt, "base64"), 64).toString("base64")}`; }
function verifyKioskPin(pin: string, stored: string) { const [, salt, expected] = stored.split("$"); if (!salt || !expected) return false; const actual = scryptSync(pin, Buffer.from(salt, "base64"), 64); const target = Buffer.from(expected, "base64"); return target.length === actual.length && timingSafeEqual(target, actual); }
function isMerchantContext(ctx: { user: { role?: string; testRole?: string; restaurantId?: number } | null }, restaurantId: number) {
  if (isAdminContext(ctx)) return true;
  if (!ctx.user || ["customer", "driver", "waiter", "kitchen", "cashier"].includes(ctx.user.testRole ?? "")) return false;
  return ctx.user.testRole === "restaurant_admin" || ctx.user.restaurantId === restaurantId;
}
function assertRestaurantAccess(ctx: { user: { role?: string; testRole?: string; restaurantId?: number } | null }, restaurantId: number) {
  if (isAdminContext(ctx)) return;
  if (ctx.user?.testRole === "restaurant_admin" && ctx.user.restaurantId === undefined) return;
  if (ctx.user?.testRole && restaurantId !== (ctx.user.restaurantId ?? 1)) throw new TRPCError({ code: "FORBIDDEN", message: "لا تملك صلاحية الوصول إلى هذا المطعم" });
}
function assertNotDriver(ctx: { user: { testRole?: string } | null }) { if (ctx.user?.testRole === "driver") throw new TRPCError({ code: "FORBIDDEN", message: "لوحة السائق تعرض الطلبات التشغيلية فقط" }); }
export function resolveMediaContext(ctx: { user: { id: number; role?: string; testRole?: string; restaurantId?: number } | null }, input: { scope?: "platform" | "restaurant" | "user"; restaurantId?: number }) {
  if (!ctx.user) throw new TRPCError({ code: "UNAUTHORIZED", message: "يجب تسجيل الدخول" });
  const isAdmin = isAdminContext(ctx);
  if (isAdmin) {
    const scope = input.scope ?? "platform";
    if (scope === "restaurant") { if (!input.restaurantId || input.restaurantId <= 0) throw new TRPCError({ code: "BAD_REQUEST", message: "حدد المطعم" }); return { scope, restaurantId: input.restaurantId, ownerUserId: undefined }; }
    if (scope === "user") return { scope, restaurantId: undefined, ownerUserId: ctx.user.id };
    return { scope: "platform" as const, restaurantId: undefined, ownerUserId: undefined };
  }
  if (ctx.user.testRole === "restaurant_admin" || ctx.user.testRole === "waiter" || ctx.user.testRole === "kitchen" || ctx.user.testRole === "cashier" || ctx.user.testRole === "driver") {
    return { scope: "restaurant" as const, restaurantId: ctx.user.restaurantId ?? 1, ownerUserId: undefined };
  }
  return { scope: "user" as const, restaurantId: undefined, ownerUserId: ctx.user.id };
}

export function detectMenuSourceLanguage(text: string): "ar" | "en" | "fr" | "ur" { if (/[\u0679\u0686\u0698\u06AF\u06BE\u06C1\u06D2\u06F0-\u06FF]/.test(text)) return "ur"; if (/[\u0600-\u06FF]/.test(text)) return "ar"; if (/[àâçéèêëîïôùûüÿœæ]/i.test(text)) return "fr"; return "en"; }
export function parseTranslationPayload(raw: unknown): unknown[] { const text = typeof raw === "string" ? raw : Array.isArray(raw) ? raw.map((part) => typeof part === "string" ? part : part && typeof part === "object" && "text" in part && typeof part.text === "string" ? part.text : "").join("") : raw && typeof raw === "object" && "text" in raw && typeof raw.text === "string" ? raw.text : ""; const cleaned = text.replace(/```(?:json)?/gi, "").replace(/```/g, "").trim(); const starts = [cleaned.indexOf("{"), cleaned.indexOf("[")].filter((index) => index >= 0); const start = starts.length ? Math.min(...starts) : -1; const endObject = cleaned.lastIndexOf("}"); const endArray = cleaned.lastIndexOf("]"); const end = Math.max(endObject, endArray); if (start < 0 || end < start) throw new Error("Invalid translation JSON"); const parsed = JSON.parse(cleaned.slice(start, end + 1)) as unknown; if (Array.isArray(parsed)) return parsed; if (parsed && typeof parsed === "object" && "translations" in parsed && Array.isArray(parsed.translations)) return parsed.translations; throw new Error("Missing translations array"); }
export function getTranslationTargetLanguages(sourceLanguage: MenuLanguage, languages: string[]): MenuLanguage[] { const supported = new Set<MenuLanguage>(["ar", "en", "fr"]); return Array.from(new Set(languages.filter((language): language is MenuLanguage => supported.has(language as MenuLanguage) && language !== sourceLanguage))); }
export function parseReceiptExtractionPayload(raw: unknown) { const text = typeof raw === "string" ? raw : Array.isArray(raw) ? raw.map((part) => typeof part === "string" ? part : part && typeof part === "object" && "text" in part && typeof part.text === "string" ? part.text : "").join("") : raw && typeof raw === "object" && "text" in raw && typeof raw.text === "string" ? raw.text : ""; const cleaned = text.replace(/```(?:json)?/gi, "").replace(/```/g, "").trim(); const start = cleaned.indexOf("{"); const end = cleaned.lastIndexOf("}"); if (start < 0 || end < start) throw new Error("Invalid receipt extraction JSON"); const parsed = JSON.parse(cleaned.slice(start, end + 1)) as { amount?: unknown; date?: unknown; confidence?: unknown }; const amount = typeof parsed.amount === "number" ? parsed.amount : typeof parsed.amount === "string" && /^\\d+(?:\\.\\d{1,2})?$/.test(parsed.amount.trim()) ? Number(parsed.amount) : null; const date = typeof parsed.date === "string" && parsed.date.trim().length <= 40 ? parsed.date.trim() || null : null; const confidence = typeof parsed.confidence === "number" && Number.isFinite(parsed.confidence) ? Math.min(1, Math.max(0, parsed.confidence)) : 0; return { amount: amount !== null && Number.isFinite(amount) ? amount.toFixed(2) : null, date, confidence: confidence.toFixed(4) }; }
export function compareReceiptAmount(orderTotal: string | number, extractedAmount: string | null) { const total = Number(orderTotal); const extracted = extractedAmount === null ? NaN : Number(extractedAmount); if (!Number.isFinite(total) || !Number.isFinite(extracted)) return { match: "unknown" as const, difference: null }; const difference = Number((extracted - total).toFixed(2)); return { match: Math.abs(difference) <= 0.01 ? "matched" as const : "mismatch" as const, difference: difference.toFixed(2) }; }
export function getTaskNotificationRecipient(task: { createdByUserId: number; assignedWorkerUserId?: number | null }, actorUserId: number) { return actorUserId === task.createdByUserId ? task.assignedWorkerUserId ?? actorUserId : task.createdByUserId; }
function normalizeMenuTagsJson(raw?: string | null) { if (!raw?.trim()) return null; try { const parsed: unknown = JSON.parse(raw); if (!Array.isArray(parsed)) throw new Error(); const tags = Array.from(new Set(parsed.filter((tag): tag is string => typeof tag === "string").map((tag) => tag.trim()).filter((tag) => tag.length >= 2 && tag.length <= 40))).slice(0, 12); return tags.length ? JSON.stringify(tags) : null; } catch { throw new TRPCError({ code: "BAD_REQUEST", message: "صيغة علامات الصنف غير صحيحة" }); } }
